export const getAchievementLabel = (course) => {
    if (!course) return 'CERTIFICATE';

    // Explicit check for 'fl-' prefix which identifies free lessons/vault items
    if (course.id?.toString().startsWith('fl-')) return 'BADGE';

    // Parse duration string (e.g., "24 Hours", "24h", "15:30")
    const durationStr = course.duration || "";

    // Try to extract hours from various formats
    let hours = 0;
    const hoursMatch = durationStr.match(/(\d+)\s*h/i);
    if (hoursMatch) {
        hours = parseInt(hoursMatch[1]);
    } else {
        // Fallback: check for colon format HH:MM
        const timeMatch = durationStr.match(/(\d+):(\d+)/);
        if (timeMatch) {
            hours = parseInt(timeMatch[1]);
        }
    }

    if (hours >= 20) return 'MASTERCLASS CERTIFICATE';
    if (hours >= 10) return 'PROFESSIONAL CERTIFICATE';
    return 'CERTIFICATE';
};

export const getAchievementTier = (course) => {
    if (!course) return { name: 'Standard', color: 'amber-600', icon: 'GraduationCap', label: 'STANDARD' };

    const label = getAchievementLabel(course);

    if (label === 'BADGE') {
        return { name: 'Skill Achievement Badge', color: 'cyan-500', icon: 'Award', label: 'SKILL BADGE' };
    } else if (label === 'MASTERCLASS CERTIFICATE') {
        return { name: 'Masterclass Certification', color: 'slate-950', icon: 'Zap', label: 'ELITE MASTERY' };
    } else if (label === 'PROFESSIONAL CERTIFICATE') {
        return { name: 'Professional Certification', color: 'indigo-600', icon: 'ShieldCheck', label: 'PRO SPECIALIST' };
    }

    return { name: 'Certificate of Completion', color: 'amber-600', icon: 'GraduationCap', label: 'STANDARD' };
};

export const durationToSeconds = (durationStr) => {
    if (!durationStr || typeof durationStr !== 'string') return 0;

    // Format: "1:20:30" or "45:00" or "1h 20m" or "45m"
    const parts = durationStr.split(':').reverse();
    if (parts.length >= 2) {
        let seconds = parseInt(parts[0]) || 0;
        let minutes = parseInt(parts[1]) || 0;
        let hours = parseInt(parts[2]) || 0;
        return seconds + (minutes * 60) + (hours * 3600);
    }

    // Handle "1h 20m" or "45m"
    let totalSeconds = 0;
    const h = durationStr.match(/(\d+)\s*h/i);
    const m = durationStr.match(/(\d+)\s*m/i);
    const s = durationStr.match(/(\d+)\s*s/i);

    if (h) totalSeconds += parseInt(h[1]) * 3600;
    if (m) totalSeconds += parseInt(m[1]) * 60;
    if (s) totalSeconds += parseInt(s[1]);

    return totalSeconds;
};
